package com.tdc.nhom6.doanjava1.controller;
import com.tdc.nhom6.doanjava1.model.*;import com.tdc.nhom6.doanjava1.service.*;import javax.servlet.http.HttpSession;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller @RequestMapping("/borrow") public class BorrowController {
 private final BorrowService borrows;public BorrowController(BorrowService b){borrows=b;}
 @GetMapping("/active") public String active(HttpSession s,Model m){Account a=(Account)s.getAttribute("currentUser");if(a==null)return "redirect:/login";m.addAttribute("account",a);m.addAttribute("records",a.canManage()?borrows.findActive():borrows.findActiveByAccount(a.getId()));return "borrow/active";}
 @GetMapping("/history") public String history(HttpSession s,Model m){Account a=(Account)s.getAttribute("currentUser");if(a==null)return "redirect:/login";m.addAttribute("account",a);m.addAttribute("records",borrows.findByAccount(a.getId()));return "borrow/history";}
 @GetMapping("/detail/{id}") public String detail(@PathVariable Long id,HttpSession s,Model m){Account a=(Account)s.getAttribute("currentUser");if(a==null)return "redirect:/login";BorrowRecord r=borrows.findById(id);if(r==null||(!a.canManage()&&!r.getAccountId().equals(a.getId())))return "redirect:/borrow/history";m.addAttribute("account",a);m.addAttribute("record",r);return "borrow/detail";}
 @GetMapping("/overdue") public String overdue(HttpSession s,Model m){Account a=(Account)s.getAttribute("currentUser");if(a==null||!a.canManage())return "redirect:/books";m.addAttribute("account",a);m.addAttribute("records",borrows.findOverdue());return "borrow/overdue";}
 @PostMapping("/request") public String request(@RequestParam Long bookId,@RequestParam(required=false)String notes,HttpSession s,RedirectAttributes ra){Account a=(Account)s.getAttribute("currentUser");if(a==null)return "redirect:/login";try{borrows.requestBorrow(a.getId(),bookId,notes);ra.addFlashAttribute("success","Đã mượn sách thành công! Hạn trả: 14 ngày.");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/books";}
 @PostMapping("/return/{id}") public String returnBook(@PathVariable Long id,HttpSession s,RedirectAttributes ra){Account a=(Account)s.getAttribute("currentUser");if(a==null||!a.canManage())return "redirect:/login";try{BorrowRecord r=borrows.returnBook(id);ra.addFlashAttribute("success",r.getFineAmount().signum()>0?"Đã trả sách. Tiền phạt: "+r.getFineAmount()+" VND":"Đã trả sách đúng hạn.");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/borrow/active";}
 @PostMapping("/pay-fine/{id}") public String payFine(@PathVariable Long id,HttpSession s,RedirectAttributes ra){Account a=(Account)s.getAttribute("currentUser");BorrowRecord r=borrows.findById(id);if(a==null||r==null||(!a.canManage()&&!r.getAccountId().equals(a.getId())))return "redirect:/borrow/history";try{borrows.payFine(id);ra.addFlashAttribute("success","Đã thanh toán tiền phạt!");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/borrow/history";}
 @PostMapping("/{recordId}/return") public String legacyReturn(@PathVariable Long recordId,HttpSession s,RedirectAttributes ra){Account a=(Account)s.getAttribute("currentUser");if(a==null)return "redirect:/login";try{borrows.returnBook(recordId,a.getId());ra.addFlashAttribute("success","Đã trả sách!");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/borrow/history";}
}